"""Exercise the real invocation API; use --live to also query Databricks."""

from __future__ import annotations

import argparse
import sys
import time
from contextlib import nullcontext
from pathlib import Path
from unittest.mock import patch
from uuid import uuid4

from databricks.sdk.service.serving import QueryEndpointResponse
from fastapi.testclient import TestClient

# Keep the deployable agent directory free of generated bytecode.
sys.dont_write_bytecode = True
sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "agent"))
from hello_agent import MODEL_ENDPOINT, app  # noqa: E402


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--live", action="store_true", help="Query the real model using SDK credentials"
    )
    args = parser.parse_args()
    invocation_id = str(uuid4())
    session_id = f"local-check-{uuid4().hex}"
    payload = {
        "id": invocation_id,
        "session_id": session_id,
        "input": {
            "messages": [
                {"role": "user", "content": "Introduce yourself in one sentence."}
            ]
        },
        "background": True,
    }
    headers = {"X-Routing-Key": session_id}
    mocked_client = (
        nullcontext() if args.live else patch("hello_agent.workspace_client")
    )
    with mocked_client as factory, TestClient(app) as client:
        if factory is not None:
            factory.return_value.serving_endpoints.query.return_value = (
                QueryEndpointResponse.from_dict(
                    {
                        "choices": [
                            {
                                "message": {
                                    "role": "assistant",
                                    "content": "A model-generated answer.",
                                }
                            }
                        ],
                        "usage": {
                            "prompt_tokens": 10,
                            "completion_tokens": 5,
                            "total_tokens": 15,
                        },
                    }
                )
            )
        response = client.post("/api/invocations", json=payload, headers=headers)
        response.raise_for_status()
        deadline = time.monotonic() + 180
        while time.monotonic() < deadline:
            response = client.get(f"/api/invocations/{invocation_id}", headers=headers)
            response.raise_for_status()
            result = response.json()
            if result["status"] == "completed":
                break
            if result["status"] in {"failed", "cancelled"}:
                raise RuntimeError(f"Invocation ended with {result['status']}")
            time.sleep(0.1)
        else:
            raise RuntimeError("Invocation did not complete within 180 seconds")

        assert result["id"] == invocation_id
        output = result["output"]
        assert output["session_id"] == session_id
        assert output["model"] == MODEL_ENDPOINT
        assert output["message"]
        assert output["usage"]["total_tokens"] > 0
        repeat = client.post("/api/invocations", json=payload, headers=headers)
        repeat.raise_for_status()
        assert repeat.json()["id"] == invocation_id
        stored = client.get(f"/api/invocations/{invocation_id}", headers=headers)
        stored.raise_for_status()
        assert stored.json()["status"] == "completed"
        assert stored.json()["output"] == result["output"]
        conflict = client.post(
            "/api/invocations",
            json={**payload, "input": {"changed": True}},
            headers=headers,
        )
        assert conflict.status_code == 409
        if factory is not None:
            query = factory.return_value.serving_endpoints.query
            query.assert_called_once()
            assert (
                query.call_args.kwargs["messages"][-1].content
                == payload["input"]["messages"][0]["content"]
            )
            assert output["message"] == "A model-generated answer."
    print(
        "PASS: background invocation, polling, model output, session, and idempotency"
    )
    print("Model:", MODEL_ENDPOINT, "(live)" if args.live else "(mocked SDK call)")
    if args.live:
        print("Answer:", output["message"])


if __name__ == "__main__":
    main()
